BEGIN;SET search_path=labassist_student,public;
\ir ../../remaining-data/tests/helpers.sql
INSERT INTO ids SELECT 'circuit',id FROM circuit_documents WHERE seed_key='DEMO_CIRCUIT_TEAM01';
INSERT INTO ids SELECT 'initial',head_version FROM circuit_documents WHERE id=(SELECT id FROM ids WHERE key='circuit');
SELECT pg_temp.ok('all projects have private example circuits',(SELECT count(*)=38 FROM circuit_documents WHERE seed_key LIKE 'DEMO_CIRCUIT_%' AND NOT team_shared));
SELECT pg_temp.ok('fifteen past examples are published as frozen versions',(SELECT count(*)=15 FROM circuit_publications));
SELECT pg_temp.reject('private circuit is not automatically a team document',$q$SELECT read_circuit(teammate,(SELECT id FROM ids WHERE key='circuit')) FROM f$q$,'access denied');
SELECT pg_temp.reject('supervisor cannot read student circuits',$q$SELECT read_circuit(supervisor,(SELECT id FROM ids WHERE key='circuit')) FROM f$q$,'access denied');
SELECT pg_temp.reject('only owner can share with team',$q$SELECT share_circuit_with_team(teammate,(SELECT id FROM ids WHERE key='circuit'),0,true,project) FROM f$q$,'owner required');
SELECT share_circuit_with_team(owner,(SELECT id FROM ids WHERE key='circuit'),0,true,project) FROM f;
SELECT pg_temp.ok('sharing freezes the owners last snapshot as checkpoint',(SELECT share_checkpoint_version=(SELECT id FROM ids WHERE key='initial') FROM circuit_documents WHERE id=(SELECT id FROM ids WHERE key='circuit')));
SELECT pg_temp.ok('teammate can read explicitly shared circuit',(SELECT jsonb_array_length(read_circuit(teammate,(SELECT id FROM ids WHERE key='circuit'))->'data'->'parts')=3 FROM f));
INSERT INTO ids SELECT 'edited',save_circuit(teammate,(SELECT id FROM ids WHERE key='circuit'),1,(SELECT data||'{"team_note":"Added by teammate"}'::jsonb FROM circuit_versions WHERE id=(SELECT id FROM ids WHERE key='initial')),'Team update') FROM f;
SELECT pg_temp.ok('prior owner version stays unchanged',NOT (SELECT data ? 'team_note' FROM circuit_versions WHERE id=(SELECT id FROM ids WHERE key='initial')));
SELECT pg_temp.reject('concurrent stale circuit save is rejected',$q$SELECT save_circuit(owner,(SELECT id FROM ids WHERE key='circuit'),1,'{"parts":[],"wires":[]}') FROM f$q$,'revision conflict');
SELECT pg_temp.reject('outsider cannot save shared team circuit',$q$SELECT save_circuit(outsider,(SELECT id FROM ids WHERE key='circuit'),2,'{"parts":[],"wires":[]}') FROM f$q$,'editable');
SELECT pg_temp.reject('invalid modeled pin is rejected',$q$SELECT save_circuit(owner,(SELECT id FROM ids WHERE key='circuit'),2,jsonb_set((SELECT data FROM circuit_versions WHERE id=(SELECT id FROM ids WHERE key='edited')),'{wires,0,to,pin}','999')) FROM f$q$,'connector mismatch');
SELECT pg_temp.reject('jumper gender is checked against connectors',$q$SELECT save_circuit(owner,(SELECT id FROM ids WHERE key='circuit'),2,jsonb_set((SELECT data FROM circuit_versions WHERE id=(SELECT id FROM ids WHERE key='edited')),'{wires,0,type}','"jumper-mm"')) FROM f$q$,'connector mismatch');
SELECT pg_temp.ok('power leads allow modeled soldered connections',wire_fit_checked('arduino-uno',1,0,'led-red',1,0,'power'));
SELECT pg_temp.ok('DC power leads cannot be used on AC supply input',NOT wire_fit_checked('s-60-12',1,0,'led-red',1,0,'power'));
SELECT pg_temp.reject('unregistered component model is rejected',$q$SELECT save_circuit(owner,(SELECT id FROM ids WHERE key='circuit'),2,jsonb_set((SELECT data FROM circuit_versions WHERE id=(SELECT id FROM ids WHERE key='edited')),'{parts,0,type}','"unknown-part"')) FROM f$q$,'sealed model');
SELECT pg_temp.reject('version history cannot be overwritten',$q$UPDATE circuit_versions SET data='{}' WHERE id=(SELECT id FROM ids WHERE key='initial')$q$,'immutable');
SELECT pg_temp.reject('search index cannot diverge from frozen snapshot',$q$INSERT INTO circuit_version_parts VALUES((SELECT id FROM ids WHERE key='initial'),'invented','led-red',1,0,0,0,'{}')$q$,'frozen version');
INSERT INTO ids SELECT 'publication',publish_circuit(owner,(SELECT id FROM ids WHERE key='circuit'),(SELECT id FROM ids WHERE key='edited'),'VIEW','Team LED reference') FROM f;
SELECT pg_temp.ok('another student can view published snapshot',(SELECT jsonb_array_length(read_published_circuit(outsider,(SELECT id FROM ids WHERE key='publication'))->'parts')=3 FROM f));
SELECT pg_temp.reject('publishing does not expose private editing workspace',$q$SELECT read_circuit(outsider,(SELECT id FROM ids WHERE key='circuit')) FROM f$q$,'access denied');
SELECT pg_temp.reject('view-only publication needs copy approval',$q$SELECT fork_circuit(outsider,(SELECT id FROM ids WHERE key='publication'),gen_random_uuid()) FROM f$q$,'approval required');
INSERT INTO ids SELECT 'request',request_circuit_copy(outsider,(SELECT id FROM ids WHERE key='publication')) FROM f;
SELECT pg_temp.ok('copy request retry has one record',(SELECT request_circuit_copy(outsider,(SELECT id FROM ids WHERE key='publication'))=(SELECT id FROM ids WHERE key='request') FROM f));
SELECT pg_temp.reject('teammate is not the publishing owner',$q$SELECT decide_circuit_copy(teammate,(SELECT id FROM ids WHERE key='request'),0,true) FROM f$q$,'owner required');
SELECT decide_circuit_copy(owner,(SELECT id FROM ids WHERE key='request'),0,true) FROM f;
INSERT INTO ids SELECT 'copy',fork_circuit(outsider,(SELECT id FROM ids WHERE key='publication'),'69000000-0000-4000-8000-000000000001') FROM f;
SELECT pg_temp.ok('approved edit creates an independent copy',(SELECT owner_id=(SELECT outsider FROM f) AND origin_version=(SELECT id FROM ids WHERE key='edited') AND id<>(SELECT id FROM ids WHERE key='circuit') FROM circuit_documents WHERE id=(SELECT id FROM ids WHERE key='copy')));
SELECT pg_temp.ok('copy retry returns the same independent document',(SELECT fork_circuit(outsider,(SELECT id FROM ids WHERE key='publication'),'69000000-0000-4000-8000-000000000001')=(SELECT id FROM ids WHERE key='copy') FROM f));
SELECT save_circuit(f.outsider,d.id,d.revision,'{"parts":[],"wires":[]}','My own edit') FROM f JOIN circuit_documents d ON d.id=(SELECT id FROM ids WHERE key='copy');
SELECT pg_temp.ok('editing copied circuit never changes original',(SELECT jsonb_array_length(v.data->'parts')=3 FROM circuit_documents d JOIN circuit_versions v ON v.id=d.head_version WHERE d.id=(SELECT id FROM ids WHERE key='circuit')));
SELECT pg_temp.ok('published search matches component names',(SELECT jsonb_array_length(search_published_circuits(outsider,'resistor'))>=15 FROM f));
SELECT pg_temp.reject('published circuit library is student-only',$q$SELECT search_published_circuits(supervisor,'') FROM f$q$,'students only');
SELECT pg_temp.reject('old completed publication has automatic copy instead of requests',$q$SELECT request_circuit_copy(outsider,(SELECT p.id FROM circuit_publications p JOIN circuit_documents d ON d.id=p.circuit_id WHERE d.seed_key='DEMO_CIRCUIT_PAST_TEAM01')) FROM f$q$,'no request required');
SELECT pg_temp.ok('completed publication can be copied without waiting',(SELECT fork_circuit(outsider,(SELECT p.id FROM circuit_publications p JOIN circuit_documents d ON d.id=p.circuit_id WHERE d.seed_key='DEMO_CIRCUIT_PAST_TEAM01'),gen_random_uuid()) IS NOT NULL FROM f));
SELECT set_circuit_publication_access(owner,(SELECT id FROM ids WHERE key='publication'),0,'COPY',true) FROM f;
SELECT pg_temp.ok('owner may allow direct editable copies',(SELECT fork_circuit(teammate,(SELECT id FROM ids WHERE key='publication'),gen_random_uuid()) IS NOT NULL FROM f));
SELECT withdraw_circuit_publication(owner,(SELECT id FROM ids WHERE key='publication'),1) FROM f;
SELECT pg_temp.reject('withdrawn publication cannot create new copies',$q$SELECT fork_circuit(outsider,(SELECT id FROM ids WHERE key='publication'),gen_random_uuid()) FROM f$q$,'not available');
SELECT pg_temp.ok('withdrawing source does not delete an existing independent copy',(SELECT read_circuit(outsider,(SELECT id FROM ids WHERE key='copy')) IS NOT NULL FROM f));
SET CONSTRAINTS ALL IMMEDIATE;ROLLBACK;
